WITH epm AS ( SELECT a.expert_id AS agent_id, LOWER(a.icp_client) AS icp_client, CAST(a."date" AS DATE) AS dt , CAST(date_add('day', 4, date_trunc('week', CAST(a."date" AS DATE))) AS DATE) AS period FROM hive.care.expert_performance_metrics a WHERE CAST(a."date" AS DATE) BETWEEN DATE '2026-05-02' AND DATE '2026-06-19' AND LOWER(a.icp_client) IN ( 'pss-verizon','pss-at&t','mob-verizon','mob-at&t' ) ), observe_data AS ( SELECT b.expert_id AS agent_id, CAST(b."date" AS DATE) AS dt, b.template_questions_name AS scorecard_name, b.behavior_name AS behavior, CAST(b.score AS DOUBLE) AS score, CAST(b.opportunity AS DOUBLE) AS opportunity FROM hive.care.l3_asurion_observe_behaviors_scores b WHERE CAST(b."date" AS DATE) BETWEEN DATE '2026-05-02' AND DATE '2026-06-19' AND b.template_questions_name IN ( 'HEROES Auto Scorecard','HEROES Auto QA Reporting - VZW' ) ) SELECT e.agent_id, e.period AS week_ending, 'all' AS call_type, o.scorecard_name, o.behavior, SUM(COALESCE(o.score, 0.0)) AS numerator, SUM(COALESCE(o.opportunity, 0.0)) AS denominator, CASE WHEN SUM(COALESCE(o.opportunity, 0.0)) = 0 THEN NULL ELSE SUM(COALESCE(o.score, 0.0)) / SUM(COALESCE(o.opportunity, 0.0)) END AS calc FROM epm e LEFT JOIN observe_data o ON e.agent_id = o.agent_id AND e.dt = o.dt GROUP BY 1,2,3,4,5
